"use client";
// @zeus-internal
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { useReducedMotion } from "motion/react";
import { useArtemisDark } from "../../../../lib/use-dark";
import { darkBeam, lightBeam } from "./beam-css";
export function AnnouncementBeam({ children }: {
    children: ReactNode;
}) {
    const dark = useArtemisDark();
    const reduced = useReducedMotion();
    const ref = useRef<HTMLDivElement>(null);
    const [paused, setPaused] = useState(false);
    const [clientReduced, setClientReduced] = useState(false);
    useLayoutEffect(() => {
        setClientReduced(Boolean(reduced && ref.current?.closest("[data-variant-index], [role=dialog]")));
    }, [reduced]);
    useEffect(() => {
        const element = ref.current;
        if (!element)
            return;
        const observer = new IntersectionObserver(([entry]) => setPaused(!entry.isIntersecting), { rootMargin: "256px", threshold: 0 });
        observer.observe(element);
        return () => observer.disconnect();
    }, []);
    return (<>
      <style>{dark ? darkBeam : lightBeam}</style>
      <div ref={ref} data-beam="c5-gradient-marquee" data-active={!reduced || (dark && !clientReduced) ? "" : undefined} data-paused={!reduced && paused ? "" : undefined} className="art:w-full" style={{ "--beam-strength": 0.68 } as CSSProperties}>
        {children}
        <div data-beam-bloom="true"/>
      </div>
    </>);
}

