        const updateVisibility = () => {
            setPageVisible(!document.hidden);
            if (document.hidden)
                setReducedRestingPose(true);
        };
        updateVisibility();
        document.addEventListener("visibilitychange", updateVisibility);
        return () => document.removeEventListener("visibilitychange", updateVisibility);
    }, []);
    useEffect(() => {
        if (!reduce || !visible || !panel.current)
            return;
        const bounds = panel.current.getBoundingClientRect();
        if (bounds.bottom < -120 || bounds.top > innerHeight + 120)
            setReducedRestingPose(true);
        const observer = new IntersectionObserver(entries => {
            if (entries.some(entry => !entry.isIntersecting))
                setReducedRestingPose(true);
        }, { rootMargin: "120px" });
        observer.observe(panel.current);
        return () => observer.disconnect();
    }, [reduce, visible]);
    useEffect(() => {
        if (!reduce || !reducedRestingPose)
            return;
        queueMicrotask(() => {
            panel.current?.querySelectorAll<HTMLElement>(".art\\:h-28").forEach((card, index) => {
                card.style.transform = `translateX(${index === 0 ? -70 : 70}px) translateY(10px) rotate(${index === 0 ? -8 : 8}deg)`;
            });
        });
    }, [reduce, reducedRestingPose, dark, embedded]);
    const active = inView && pageVisible && !reduce;
    return (<>
